CREATE TABLE core_data_usage(scope TEXT PRIMARY KEY, rows INTEGER NOT NULL CHECK(rows>=0), bytes INTEGER NOT NULL CHECK(bytes>=0));
CREATE TABLE core_groups(scope TEXT NOT NULL,id TEXT NOT NULL,parent_id TEXT NOT NULL,invocation_id TEXT NOT NULL,group_key TEXT NOT NULL,body BLOB NOT NULL,plan_digest TEXT NOT NULL,membership_digest TEXT NOT NULL,member_count INTEGER NOT NULL CHECK(member_count BETWEEN 0 AND 1000),sealed INTEGER NOT NULL CHECK(sealed IN (0,1)),PRIMARY KEY(scope,id),UNIQUE(scope,parent_id,invocation_id,group_key));
CREATE INDEX core_groups_parent ON core_groups(scope,parent_id,id);
CREATE TABLE core_group_members(scope TEXT NOT NULL,group_id TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 999),item_key TEXT NOT NULL,child_id TEXT NOT NULL,event_id TEXT NOT NULL,parameters BLOB NOT NULL,fact_digest TEXT NOT NULL,event_body BLOB NOT NULL,link_body BLOB NOT NULL,member_body BLOB NOT NULL,PRIMARY KEY(scope,group_id,ordinal),UNIQUE(scope,group_id,item_key),UNIQUE(scope,child_id),UNIQUE(scope,event_id),FOREIGN KEY(scope,group_id) REFERENCES core_groups(scope,id));
CREATE VIEW core_group_events AS SELECT m.scope,m.event_id,m.child_id,m.group_id,m.event_body,m.parameters FROM core_group_members m JOIN core_groups g ON g.scope=m.scope AND g.id=m.group_id WHERE g.sealed=1;
CREATE VIEW core_child_links AS SELECT m.scope,m.child_id,g.parent_id,g.invocation_id,m.group_id,m.ordinal,m.link_body,m.parameters FROM core_group_members m JOIN core_groups g ON g.scope=m.scope AND g.id=m.group_id WHERE g.sealed=1;
CREATE TABLE core_namespaces(scope TEXT NOT NULL,domain TEXT NOT NULL,id TEXT NOT NULL,parent_id TEXT,name TEXT NOT NULL,name_key TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),body BLOB NOT NULL,PRIMARY KEY(scope,domain,id),FOREIGN KEY(scope,domain,parent_id) REFERENCES core_namespaces(scope,domain,id));
CREATE UNIQUE INDEX core_namespace_names ON core_namespaces(scope,domain,coalesce(parent_id,''),name_key) WHERE archived=0;
CREATE INDEX core_namespace_children ON core_namespaces(scope,domain,parent_id,id) WHERE archived=0;
CREATE TABLE core_resources(scope TEXT NOT NULL,domain TEXT NOT NULL,id TEXT NOT NULL,namespace_id TEXT,name TEXT NOT NULL,name_key TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),main_commit_id TEXT NOT NULL,archived INTEGER NOT NULL CHECK(archived IN (0,1)),origin_resource_id TEXT NOT NULL,origin_commit_id TEXT NOT NULL,body BLOB NOT NULL,PRIMARY KEY(scope,domain,id),FOREIGN KEY(scope,domain,namespace_id) REFERENCES core_namespaces(scope,domain,id));
CREATE UNIQUE INDEX core_resource_names ON core_resources(scope,domain,coalesce(namespace_id,''),name_key) WHERE archived=0;
CREATE UNIQUE INDEX core_resource_system_keys ON core_resources(scope,domain,json_extract(CAST(body AS TEXT),'$.system_key')) WHERE json_extract(CAST(body AS TEXT),'$.system')=1 AND json_extract(CAST(body AS TEXT),'$.system_key')<>'';
CREATE INDEX core_resources_namespace ON core_resources(scope,domain,namespace_id,id) WHERE archived=0;
CREATE TABLE core_branches(scope TEXT NOT NULL,domain TEXT NOT NULL,id TEXT NOT NULL,resource_id TEXT NOT NULL,name_key TEXT NOT NULL,head_commit_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),body BLOB NOT NULL,PRIMARY KEY(scope,domain,id),FOREIGN KEY(scope,domain,resource_id) REFERENCES core_resources(scope,domain,id));
CREATE UNIQUE INDEX core_branch_live_names ON core_branches(scope,domain,resource_id,name_key) WHERE coalesce(json_extract(CAST(body AS TEXT),'$.archived_at'),'')='';
CREATE INDEX core_branch_heads ON core_branches(scope,domain,resource_id,head_commit_id,id);
CREATE TABLE core_snapshots(scope TEXT NOT NULL,domain TEXT NOT NULL,id TEXT NOT NULL,resource_id TEXT NOT NULL,branch_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),source_commit_id TEXT NOT NULL,content_digest TEXT NOT NULL,payload BLOB NOT NULL,manifest BLOB NOT NULL,body BLOB NOT NULL,PRIMARY KEY(scope,domain,id),UNIQUE(scope,domain,resource_id,version),FOREIGN KEY(scope,domain,resource_id) REFERENCES core_resources(scope,domain,id),FOREIGN KEY(scope,domain,branch_id) REFERENCES core_branches(scope,domain,id));
CREATE TABLE core_references(scope TEXT NOT NULL,domain TEXT NOT NULL,commit_id TEXT NOT NULL,slot TEXT NOT NULL,target_domain TEXT NOT NULL,target_resource_id TEXT NOT NULL,target_commit_id TEXT NOT NULL,body BLOB NOT NULL,PRIMARY KEY(scope,domain,commit_id,slot),FOREIGN KEY(scope,domain,commit_id) REFERENCES core_snapshots(scope,domain,id));
CREATE INDEX core_reference_targets ON core_references(scope,target_domain,target_resource_id,target_commit_id);
CREATE TABLE core_changes(scope TEXT NOT NULL,id TEXT NOT NULL,domain TEXT NOT NULL,entity_id TEXT NOT NULL,body BLOB NOT NULL,PRIMARY KEY(scope,id));
CREATE INDEX core_changes_entity ON core_changes(scope,domain,entity_id,id);
CREATE TABLE core_configuration_domains(domain TEXT PRIMARY KEY,schema_identity TEXT NOT NULL,schema_version INTEGER NOT NULL CHECK(schema_version>0),registry_digest TEXT NOT NULL,capabilities BLOB NOT NULL,main_visibility INTEGER NOT NULL CHECK(main_visibility IN (0,1)),system_provisioning INTEGER NOT NULL CHECK(system_provisioning IN (0,1)));
CREATE TABLE core_configuration_receipts(scope TEXT NOT NULL,domain TEXT NOT NULL,mutation_key TEXT NOT NULL,intent_digest TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN ('resource.create','resource.commit','configuration.branch.create','configuration.branch.archive','configuration.resource.state','configuration.resource.metadata')),plan_digest TEXT NOT NULL,body BLOB NOT NULL,PRIMARY KEY(scope,domain,mutation_key),FOREIGN KEY(domain) REFERENCES core_configuration_domains(domain));
CREATE TABLE core_catalog_receipts(scope TEXT NOT NULL,domain TEXT NOT NULL,mutation_key TEXT NOT NULL,intent_digest TEXT NOT NULL,operation TEXT NOT NULL,body BLOB NOT NULL,PRIMARY KEY(scope,domain,mutation_key),FOREIGN KEY(domain) REFERENCES core_configuration_domains(domain));
CREATE TABLE core_execution_identity(id INTEGER PRIMARY KEY CHECK(id=1),token TEXT NOT NULL);
CREATE TABLE core_commands(scope TEXT NOT NULL,command_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('accepted','succeeded','failed','rejected')),action TEXT NOT NULL,target TEXT NOT NULL,body BLOB NOT NULL,PRIMARY KEY(scope,command_id),UNIQUE(scope,idempotency_key));
CREATE INDEX core_commands_accepted ON core_commands(scope,action,command_id) WHERE status='accepted';
CREATE INDEX core_commands_stop_fence ON core_commands(scope,target,action,command_id) WHERE status IN ('accepted','succeeded');
CREATE TABLE core_event_offsets(scope TEXT PRIMARY KEY,last_offset INTEGER NOT NULL CHECK(last_offset>=0));
CREATE TABLE core_event_sequences(scope TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,last_seq INTEGER NOT NULL CHECK(last_seq>=0),PRIMARY KEY(scope,entity_type,entity_id));
CREATE TABLE core_execution_events(scope TEXT NOT NULL,offset INTEGER NOT NULL CHECK(offset>0),entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,seq INTEGER NOT NULL CHECK(seq>0),type TEXT NOT NULL,body BLOB NOT NULL,PRIMARY KEY(scope,offset),UNIQUE(scope,entity_type,entity_id,seq));
CREATE INDEX core_execution_events_entity ON core_execution_events(scope,entity_type,entity_id,offset);
CREATE INDEX core_execution_events_entity_type ON core_execution_events(scope,entity_type,offset);
CREATE INDEX core_execution_events_entity_id ON core_execution_events(scope,entity_id,offset);
CREATE INDEX core_execution_events_type ON core_execution_events(scope,type,offset);
